const $=id=>document.getElementById(id);
const parts=[
{id:'ra',name:'Right atrium',sub:'Upper chamber · Patient’s right',en:'Receives oxygen-poor blood returning from the body through the venae cavae.',ha:'Wannan ɗakin na sama a gefen dama yana karɓar jini mai ƙarancin oxygen daga jiki ta venae cavae.',link:'Venae cavae → right atrium → tricuspid valve'},
{id:'rv',name:'Right ventricle',sub:'Lower chamber · Patient’s right',en:'Pumps blood through the pulmonary valve and pulmonary arteries to the lungs.',ha:'Wannan ɗakin na ƙasa a gefen dama yana tura jini zuwa huhu ta pulmonary valve da pulmonary arteries.',link:'Right ventricle → pulmonary valve → lungs'},
{id:'la',name:'Left atrium',sub:'Upper chamber · Patient’s left',en:'Receives oxygen-rich blood from the lungs through the pulmonary veins.',ha:'Wannan ɗakin na sama a gefen hagu yana karɓar jini mai oxygen da yawa daga huhu ta pulmonary veins.',link:'Pulmonary veins → left atrium → mitral valve'},
{id:'lv',name:'Left ventricle',sub:'Lower chamber · Patient’s left',en:'Pumps blood through the aortic valve into the aorta to supply the body.',ha:'Wannan ɗakin na ƙasa a gefen hagu yana tura jini ta aortic valve zuwa aorta domin ya isa sassan jiki.',link:'Left ventricle → aortic valve → aorta'}];
function read(k,f){try{return JSON.parse(localStorage.getItem(k))??f}catch{return f}}
function save(k,v){try{localStorage.setItem(k,JSON.stringify(v));return true}catch{return false}}
let visited=new Set(read('jiki-visited',[]).filter(x=>parts.some(p=>p.id===x))),current=0,language=read('jiki-language','both'),timer=null,step=0;
function progress(){ $('progressText').textContent=`${visited.size} of 4 chambers explored`;$('progress').value=visited.size;const best=read('jiki-best',null);$('best').textContent=best===null?'Quiz not attempted yet':`Best practice score: ${best} / 5`; }
function selectPart(i,track=true){current=i;const p=parts[i];document.querySelectorAll('.chamber').forEach(c=>{c.classList.toggle('selected',c.id===p.id);c.setAttribute('aria-pressed',String(c.id===p.id))});$('partKind').textContent=`CHAMBER 0${i+1} / 04`;$('partTitle').textContent=p.name;$('partSub').textContent=p.sub;$('partEn').textContent=p.en;$('partHa').textContent=p.ha;$('connection').textContent=p.link;if(track){visited.add(p.id);save('jiki-visited',[...visited]);progress()}$('nextPart').innerHTML=i===3?'Follow the blood <span>→</span>':'Next chamber <span>→</span>';}
parts.forEach((p,i)=>{const c=$(p.id);c.onclick=()=>selectPart(i);c.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();selectPart(i)}}});
$('nextPart').onclick=()=>{visited.add(parts[current].id);save('jiki-visited',[...visited]);progress();if(current<3)selectPart(current+1);else show('flow')};
$('labels').onclick=()=>{const hide=$('heart').classList.toggle('hide-labels');$('labels').textContent=hide?'Show labels':'Hide labels';$('labels').setAttribute('aria-pressed',String(hide))};
function setLang(){document.body.classList.remove('en','ha');if(language!=='both')document.body.classList.add(language);$('language').value=language;save('jiki-language',language)}$('language').onchange=e=>{language=e.target.value;setLang()};
function stop(){clearInterval(timer);timer=null;$('play').textContent='Play sequence'}
function show(view){stop();document.querySelectorAll('.view').forEach(v=>v.hidden=v.id!==view);document.querySelectorAll('[data-view]').forEach(b=>{b.classList.toggle('active',b.dataset.view===view);b.setAttribute('aria-current',b.dataset.view===view?'page':'false')});if(view==='flow')renderFlow();if(view==='quiz')renderQuiz()}
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>show(b.dataset.view));
const flow=[
['Body → venae cavae','Blood returns from the body.','Jini yana dawowa daga sassan jiki.'],
['Right atrium','The receiving chamber on the right.','Ɗakin da ke karɓar jini a gefen dama.'],
['Tricuspid valve','The gateway to the right ventricle.','Jini yana bi ta nan zuwa right ventricle.'],
['Right ventricle','The pump for the lung circuit.','Yana tura jini zuwa huhu.'],
['Pulmonary valve → arteries','Blood travels away from the heart to the lungs.','Jini yana tafiya daga zuciya zuwa huhu.'],
['Lungs','Blood gains oxygen and releases carbon dioxide.','Jini yana karɓar oxygen, yana kuma sakin carbon dioxide.'],
['Pulmonary veins','Blood returns to the heart.','Jini yana dawowa zuwa zuciya.'],
['Left atrium','The receiving chamber on the left.','Ɗakin da ke karɓar jini a gefen hagu.'],
['Mitral valve','The gateway to the left ventricle.','Jini yana bi ta nan zuwa left ventricle.'],
['Left ventricle','The pump for the body circuit.','Yana tura jini zuwa sassan jiki.'],
['Aortic valve → aorta → body','The circuit continues through the body.','Jini yana zagayawa cikin jiki, sannan ya dawo zuciya.']];
function renderFlow(){ $('stepcount').textContent=`${step+1} / ${flow.length}`;$('flowlist').innerHTML=flow.map((f,i)=>`<li><button data-step="${i}" class="${i===step?'current':''}" aria-current="${i===step?'step':'false'}"><span>${String(i+1).padStart(2,'0')}</span>${f[0]}</button></li>`).join('');document.querySelectorAll('[data-step]').forEach(b=>b.onclick=()=>{stop();step=+b.dataset.step;renderFlow()});const f=flow[step];$('stepdetail').innerHTML=`<div class="bigstep">${String(step+1).padStart(2,'0')}</div><div class="eyebrow">FOLLOW THE CIRCUIT</div><h3>${f[0]}</h3><p class="lang-en">${f[1]}</p><p class="lang-ha" lang="ha">${f[2]}</p>`;$('prev').disabled=step===0;$('next').textContent=step===flow.length-1?'Restart ↺':'Next →'}
$('prev').onclick=()=>{stop();step=Math.max(0,step-1);renderFlow()};$('next').onclick=()=>{stop();step=(step+1)%flow.length;renderFlow()};$('play').onclick=()=>{if(timer){stop();return}if(step===flow.length-1)step=0;renderFlow();$('play').textContent='Pause sequence';timer=setInterval(()=>{if(step<flow.length-1){step++;renderFlow()}else stop()},2500)};
const quiz=[
{q:'Which chamber first receives blood returning from the body?',ha:'Wane ɗaki ne yake fara karɓar jinin da ya dawo daga jiki?',a:['Left atrium','Right atrium','Left ventricle','Right ventricle'],c:1,e:'The venae cavae deliver returning blood to the right atrium.',h:'Venae cavae suna kawo jinin da ya dawo daga jiki zuwa right atrium.'},
{q:'What comes immediately after the right ventricle in the blood-flow route?',ha:'Mene ne jini yake bi kai tsaye bayan right ventricle?',a:['Aortic valve','Mitral valve','Pulmonary valve','Left atrium'],c:2,e:'Blood passes through the pulmonary valve on its way to the lungs.',h:'Jini yana bi ta pulmonary valve a hanyarsa ta zuwa huhu.'},
{q:'Which vessels carry oxygen-rich blood from the lungs to the heart?',ha:'Waɗanne jijiyoyi ne suke kawo jini mai oxygen daga huhu zuwa zuciya?',a:['Venae cavae','Pulmonary arteries','Aorta','Pulmonary veins'],c:3,e:'Pulmonary veins return blood to the left atrium. A vein is defined by flow toward the heart, not by oxygen level.',h:'Pulmonary veins suna dawo da jini zuwa left atrium. Ana kiran jijiya vein saboda tana kawo jini zuwa zuciya, ba saboda yawan oxygen ba.'},
{q:'Why does the left ventricle have a thicker muscular wall?',ha:'Me ya sa bangon tsokar left ventricle ya fi kauri?',a:['It produces higher pressure for the body circuit','It receives blood directly from the body','It stores oxygen','It pumps only to the lungs'],c:0,e:'The systemic circuit requires a higher driving pressure than the pulmonary circuit.',h:'Zagayar jini zuwa sassan jiki tana buƙatar matsin da ya fi na zagayar jini zuwa huhu.'},
{q:'What is the main role of the heart valves?',ha:'Mene ne babban aikin bawulolin zuciya?',a:['Add oxygen to blood','Create red blood cells','Help prevent backward flow','Separate oxygen from carbon dioxide'],c:2,e:'Valves open and close to support forward flow and prevent backflow.',h:'Bawuloli suna buɗewa da rufewa domin jini ya ci gaba ta hanyarsa, ba ya komawa baya.'}];
let qi=0,answers=[],complete=false;
function renderQuiz(){if(complete){const score=answers.filter((a,i)=>a===quiz[i].c).length;$('quizbody').innerHTML=`<div class="score">${score}<span style="font-size:25px"> / 5</span></div><h3>${score===5?'You connected the whole circuit.':'Good practice. Keep building the connections.'}</h3><p>${score===5?'Now try explaining the circuit in your own words.':'Review your explanations, then try again.'}</p><div class="controls"><button class="primary" id="retry">Practise again ↺</button><button class="subtle" id="review">Review answers</button></div><div id="reviewlist"></div>`;$('retry').onclick=()=>{qi=0;answers=[];complete=false;renderQuiz()};$('review').onclick=()=>{$('reviewlist').innerHTML=quiz.map((q,i)=>`<details style="margin-top:18px"><summary>${i+1}. ${answers[i]===q.c?'Correct':'Revisit'} — ${q.q}</summary><p>Your answer: ${q.a[answers[i]]}<br>Correct answer: ${q.a[q.c]}</p><p class="lang-en">${q.e}</p><p class="lang-ha" lang="ha">${q.h}</p></details>`).join('')};return}const q=quiz[qi],answered=answers[qi]!==undefined;$('quizbody').innerHTML=`<div class="question"><div class="eyebrow">QUESTION ${qi+1} OF ${quiz.length}</div><h3 class="lang-en">${q.q}</h3><p class="lang-ha" lang="ha">${q.ha}</p><div class="answers">${q.a.map((a,i)=>`<button class="answer ${answered&&i===q.c?'correct':''} ${answered&&i===answers[qi]&&i!==q.c?'wrong':''}" data-answer="${i}" ${answered?'disabled':''}>${String.fromCharCode(65+i)}. ${a}</button>`).join('')}</div>${answered?`<div class="feedback" role="status"><strong>${answers[qi]===q.c?'Correct.':'Let’s clarify that.'}</strong><p class="lang-en">${q.e}</p><p class="lang-ha" lang="ha">${q.h}</p></div><button style="margin-top:20px" class="primary" id="nextQuestion">${qi===4?'See my result':'Next question'} →</button>`:''}</div>`;document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{answers[qi]=+b.dataset.answer;renderQuiz()});if(answered)$('nextQuestion').onclick=()=>{if(qi<4)qi++;else{complete=true;const score=answers.filter((a,i)=>a===quiz[i].c).length;save('jiki-best',Math.max(read('jiki-best',0),score));progress()}renderQuiz()}}
$('notepad').value=read('jiki-notes','');$('notepad').oninput=()=>{$('saved').textContent=save('jiki-notes',$('notepad').value)?'Saved in this browser.':'Browser storage unavailable. Download to keep your notes.'};$('download').onclick=()=>{const blob=new Blob(['Jiki — Heart & circulation\n\n'+$('notepad').value],{type:'text/plain;charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='jiki-heart-revision.txt';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};
setLang();selectPart(0,false);progress();renderFlow();renderQuiz();
